var import_obsidian4 = require("obsidian");
var PreparedTopicSuggestModal = class extends import_obsidian4.SuggestModal {
  constructor(app, topics, onChoose) {
    super(app);
    this.topics = topics;
    this.onChoose = onChoose;
    this.setPlaceholder("\u8F93\u5165\u5173\u952E\u8BCD\u7B5B\u9009\u5019\u9009\u4E3B\u9898\u2026");
  }
  getSuggestions(query) {
    const q = query.toLowerCase().trim();
    if (!q) return [...this.topics];
    return this.topics.filter(
      (t) => t.title.toLowerCase().includes(q) || t.description.toLowerCase().includes(q)
    );
  }
  renderSuggestion(topic, el) {
    let statusLabel2 = "";
    if (topic.status === "in_progress") {
      statusLabel2 = " [\u7EE7\u7EED\u8BA8\u8BBA]";
    } else if (topic.status === "discussed") {
      statusLabel2 = " [\u91CD\u65B0\u8BA8\u8BBA]";
    }
    el.createEl("div", { text: topic.title + statusLabel2, cls: "pcc-suggest-title" });
    el.createEl("small", {
      text: topic.description.slice(0, 120) + (topic.description.length > 120 ? "\u2026" : ""),
      cls: "pcc-suggest-desc"
    });
    const stars = Math.round(topic.relevance_score * 5);
    el.createEl("span", {
      text: `  ${"\u2605".repeat(stars)}${"\u2606".repeat(5 - stars)}`,
      cls: "pcc-suggest-score"
    });
    if (topic.is_news_related) {
      el.createEl("span", {
        text: " \u{1F525}\u70ED\u70B9",
        cls: "pcc-suggest-tag pcc-suggest-tag--hot"
      });
    }
  }
  onChooseSuggestion(topic) {
    this.onChoose(topic);
  }
};

